import matter from 'gray-matter';

export interface PageFrontmatter {
  title: string;
  date: string;
  tags: string[];
  template?: string;
  layout?: string;
}

export interface PageData {
  slug: string;
  frontmatter: PageFrontmatter;
  content: string;
  html: string;
